import{_ as p,a0 as o,w as d,s as r,ao as n,I as i,x as e,a1 as l,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"Linux 工具：點的含義 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 工具：點的含義 | LCTT (201901) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 工具：點的含義 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 工具：點的含義 | LCTT (201901) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201901/20190115 Linux Tools- The Meaning of Dot","title":"Linux 工具：點的含義","tag":"201901","desc":""},"relativePath":"201901/20190115 Linux Tools- The Meaning of Dot.md","filePath":"[post].md"}'),h={name:"201901/20190115 Linux Tools- The Meaning of Dot.md"};function c(g,s,u,k,b,f){const a=o("Link");return d(),r("div",null,[s[26]||(s[26]=n(`<h1 id="linux-工具-點的含義" tabindex="-1">Linux 工具：點的含義 <a class="header-anchor" href="#linux-工具-點的含義" aria-label="Permalink to “Linux 工具：點的含義”">​</a></h1><blockquote><p>Paul Brown 解釋了 Linux shell 命令中那個不起眼的“點”的各種意思和用法。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/psychedelic-dot.jpg?itok=giKEHvwQ" alt=""></p><p>在現實情況中，使用 shell 命令編寫的單行命令或腳本可能會令人很困惑。你使用的很多工具的名稱與它們的實際功能相差甚遠（<code>grep</code>、<code>tee</code> 和 <code>awk</code>，還有嗎？），而當你將兩個或更多個組合起來時，所組成的 “句子” 看起來更像某種外星人的天書。</p><p>因此，上面説的這些對於你並無幫助，因為你用來編寫一連串的指令所使用的符號根據你使用的場景有着不同的意義。</p><h3 id="位置、位置、位置" tabindex="-1">位置、位置、位置 <a class="header-anchor" href="#位置、位置、位置" aria-label="Permalink to “位置、位置、位置”">​</a></h3><p>就拿這個不起眼的點（<code>.</code>）來説吧。當它放在一個需要一個目錄名稱的命令的參數處時，表示“當前目錄”：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find . -name &quot;*.jpg&quot;</span></span></code></pre></div><p>意思就是“在當前目錄（包括子目錄）中尋找以 <code>.jpg</code> 結尾的文件”。</p><p><code>ls .</code> 和 <code>cd .</code> 結果也如你想的那樣，它們分別列舉和“進入”到當前目錄，雖然在這兩種情況下這個點都是多餘的。</p><p>而一個緊接着另一個的兩個點呢，在同樣的場景下（即當你的命令期望一個文件目錄的時候）表示“當前目錄的父目錄”。如果你當前在 <code>/home/your_directory</code> 下並且運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd ..</span></span></code></pre></div><p>你就會進入到 <code>/home</code>。所以，你可能認為這仍然適合“點代表附近目錄”的敍述，並且毫不復雜，對吧？</p><p>那下面這樣會怎樣呢？如果你在一個文件或目錄的開頭加上點，它表示這個文件或目錄會被隱藏：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ touch somedir/file01.txt somedir/file02.txt somedir/.secretfile.txt</span></span>
<span class="line"><span>$ ls -l somedir/</span></span>
<span class="line"><span>total 0</span></span>
<span class="line"><span>-rw-r--r-- 1 paul paul 0 Jan 13 19:57 file01.txt</span></span>
<span class="line"><span>-rw-r--r-- 1 paul paul 0 Jan 13 19:57 file02.txt</span></span>
<span class="line"><span>$ # 注意上面列舉的文件中沒有 .secretfile.txt</span></span>
<span class="line"><span>$ ls -la somedir/</span></span>
<span class="line"><span>total 8</span></span>
<span class="line"><span>drwxr-xr-x 2 paul paul 4096 Jan 13 19:57 .</span></span>
<span class="line"><span>drwx------ 48 paul paul 4096 Jan 13 19:57 ..</span></span>
<span class="line"><span>-rw-r--r-- 1 paul paul 0 Jan 13 19:57 file01.txt</span></span>
<span class="line"><span>-rw-r--r-- 1 paul paul 0 Jan 13 19:57 file02.txt</span></span>
<span class="line"><span>-rw-r--r-- 1 paul paul 0 Jan 13 19:57 .secretfile.txt</span></span>
<span class="line"><span>$ # 這個 -a  選項告訴 ls 去展示“all”文件，包括那些隱藏的</span></span></code></pre></div><p>然後就是你可以將 <code>.</code> 當作命令。是的，你聽我説：<code>.</code> 是個真真正正的命令。它是 <code>source</code> 命令的代名詞，所以你可以用它在當前 shell 中執行一個文件，而不是以某種其它的方式去運行一個腳本文件（這通常指的是 Bash 會產生一個新的 shell 去運行它）</p><p>很困惑？別擔心 —— 試試這個：創建一個名為 <code>myscript</code> 的腳本，內容包含下面一行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>myvar=&quot;Hello&quot;</span></span></code></pre></div><p>然後通過常規的方法執行它，也就是用 <code>sh myscript</code>（或者通過 <code>chmod a+x myscript</code> 命令讓它可執行，然後運行 <code>./myscript</code>）。現在嘗試並且觀察 <code>myvar</code> 的內容，通過 <code>echo $myvar</code>（理所當然你什麼也得不到）。那是因為，當你的腳本賦值 <code>&quot;Hello&quot;</code> 給 <code>myvar</code> 時，它是在一個隔離的bash shell 實例中進行的。當腳本運行結束時，這個新產生的實例會消失並且將控制權轉交給原來的shell，而原來的 shell 裏甚至都不存在 <code>myvar</code> 變量。</p><p>然而，如果你這樣運行 <code>myscript</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>. myscript</span></span></code></pre></div><p><code>echo $myvar</code> 就會打印 <code>Hello</code> 到命令列上。</p>`,22)),i("p",null,[s[1]||(s[1]=e("當你的 ",-1)),s[2]||(s[2]=i("code",null,".bashrc",-1)),s[3]||(s[3]=e(" 文件發生變化後，你經常會用到 ",-1)),s[4]||(s[4]=i("code",null,".",-1)),s[5]||(s[5]=e("（或 ",-1)),s[6]||(s[6]=i("code",null,"source",-1)),s[7]||(s[7]=e("）命令，",-1)),l(a,{href:"https://www.linux.com/blog/learn/2018/12/bash-variables-environmental-and-otherwise"},{default:t(()=>[...s[0]||(s[0]=[e("就像當你要擴展 ",-1),i("code",null,"PATH",-1),e(" 變量那樣",-1)])]),_:1}),s[8]||(s[8]=e("。在你的當前 shell 實例中，你可以使用 ",-1)),s[9]||(s[9]=i("code",null,".",-1)),s[10]||(s[10]=e(" 來讓變化立即生效。",-1))]),s[27]||(s[27]=n('<h3 id="雙重麻煩" tabindex="-1">雙重麻煩 <a class="header-anchor" href="#雙重麻煩" aria-label="Permalink to “雙重麻煩”">​</a></h3><p>就像看似無關緊要的一個點有多個含義一樣，兩個點也是如此。除了指向當前目錄的父級之外，兩個點（<code>..</code>）也用於構建序列。</p><p>嘗試下這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo {1..10}</span></span></code></pre></div><p>它會打印出從 1 到 10 的序列。在這種場景下，<code>..</code> 表示 “從左邊的值開始，計數到右邊的值”。</p><p>現在試下這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo {1..10..2}</span></span></code></pre></div><p>你會得到 <code>1 3 5 7 9</code>。<code>..2</code> 這部分命令告訴 Bash 輸出這個序列，不過不是每個相差 1，而是相差 2。換句話説，就是你會得到從 1 到 10 之間的奇數。</p><p>它反着也仍然有效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo {10..1..2}</span></span></code></pre></div><p>你也可以用多個 0 填充你的數字。這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo {000..121..2}</span></span></code></pre></div><p>會這樣打印出從 0 到 121 之間的偶數（填充了前置 0）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>000 002 004 006 ... 050 052 054 ... 116 118 120</span></span></code></pre></div><p>不過這樣的序列發生器有啥用呢？當然，假設您的新年決心之一是更加謹慎控制您的帳户花銷。作為決心的一部分，您需要創建目錄，以便對過去 10 年的數字發票進行分類：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir {2009..2019}_Invoices</span></span></code></pre></div><p>工作完成。</p><p>或者你可能有數百個帶編號的文件，比如從視頻剪輯中提取的幀，或許因為某種原因，你只想從第 43 幀到第 61 幀每隔三幀刪除一幀：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm frame_{043..61..3}</span></span></code></pre></div><p>很可能，如果你有超過 100 個幀，它們將以填充 0 命名，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>frame_000 frame_001 frame_002 ...</span></span></code></pre></div><p>那就是為什麼你在命令中要用 <code>043</code>，而不是<code>43</code> 的原因。</p><h3 id="花括號花招" tabindex="-1">花括號花招 <a class="header-anchor" href="#花括號花招" aria-label="Permalink to “花括號花招”">​</a></h3><p>説實話，序列的神奇之處不在於雙點，而是花括號（<code>{}</code>）的巫術。看看它對於字母是如何工作的。這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch file_{a..z}.txt</span></span></code></pre></div><p>它創建了從 <code>file_a.txt</code> 到 <code>file_z.txt</code> 的文件。</p><p>但是，你必須小心。使用像 <code>{Z..a}</code> 這樣的序列將產生一大堆大寫字母和小寫字母之間的非字母、數字的字符（既不是數字或字母的字形）。其中一些字形是不可打印的或具有自己的特殊含義。使用它們來生成文件名稱可能會導致一系列意外和可能令人不快的影響。</p><p>最後一件值得指出的事：包圍在 <code>{...}</code> 的序列，它們也可以包含字符串列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>touch {blahg, splurg, mmmf}_file.txt</span></span></code></pre></div><p>將創建了 <code>blahg_file.txt</code>、<code>splurg_file.txt</code> 和 <code>mmmf_file.txt</code>。</p><p>當然，在別的場景中，大括號也有不同的含義（驚喜嗎！）。不過那是別的文章的內容了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Bash 以及運行於其中的各種工具已經被尋求解決各種特定問題的系統管理員們把玩了數十年。要説這種有自己之道的系統管理員是一種特殊物種的話，那是有點輕描淡寫。總而言之，與其他語言相反，Bash 的設計目標並不是為了用户友好、簡單、甚至合乎邏輯。</p><p>但這並不意味着它不強大 —— 恰恰相反。Bash 的語法和 shell 工具可能不一致且很龐大，但它們也提供了一系列令人眼花繚亂的方法來完成您可能想像到的一切。就像有一個工具箱，你可以從中找到從電鑽到勺子的所有東西，以及橡皮鴨、一卷膠帶和一些指甲鉗。</p><p>除了引人入勝之外，探明你可以直接在 shell 中達成的所有能力也很有趣，所以下次我們將深入探討如何構建更大更好的 Bash 命令列。</p><p>在那之前，玩得開心！</p><hr>',37)),i("p",null,[s[12]||(s[12]=e("via: ",-1)),l(a,{href:"https://www.linux.com/blog/learn/2019/1/linux-tools-meaning-dot"},{default:t(()=>[...s[11]||(s[11]=[e("https://www.linux.com/blog/learn/2019/1/linux-tools-meaning-dot",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=e("作者：",-1)),l(a,{href:"https://www.linux.com/users/bro66"},{default:t(()=>[...s[13]||(s[13]=[e("Paul Brown",-1)])]),_:1}),s[18]||(s[18]=e(" 選題：",-1)),l(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[14]||(s[14]=[e("lujun9972",-1)])]),_:1}),s[19]||(s[19]=e(" 譯者：",-1)),l(a,{href:"https://github.com/asche910"},{default:t(()=>[...s[15]||(s[15]=[e("asche910",-1)])]),_:1}),s[20]||(s[20]=e(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[23]||(s[23]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[e("Linux中國",-1)])]),_:1}),s[25]||(s[25]=e(" 榮譽推出",-1))])])}const C=p(h,[["render",c]]);export{y as __pageData,C as default};
